  _ = `Eventos especiais do Steam Next Fest`,
  _ = `Mais sobre o Steam Next Fest`,
  _ = `Opcional: pode criar até dois eventos do seguinte tipo durante o Steam Next Fest.`,
  _ = `Este tipo só pode ser usado para eventos novos, não para eventos já publicados.`,
  _ = `Como membro da equipa de apoio da Valve, pode ignorar este limite. Tenha em atenção que a alteração de um evento publicado não conta para o limite máximo permitido.`,
  _ = `Lamentamos, mas o limite de eventos deste tipo foi alcançado (%1$s) e não é possível publicar mais.`,
