  _ = `Contacte o apoio para developers`,
  _ = `Como membro da equipa de apoio da Valve, pode ignorar este limite. Para tal, terá de definir e publicar o evento em nome do parceiro Steamworks.`,
  _ = `Steam Next Fest: Apresentação rápida`,
  _ = `Use isto para disponibilizar aos utilizadores do Steam detalhes interessantes sobre a sua equipa de desenvolvimento, o conteúdo da sua demo e como esta se relaciona com o seu jogo. As informações que nos fornecer serão destacadas na página do seu jogo na Loja Steam e com o seu jogo nas páginas do Steam Next Fest.`,
  _ = `Steam Next Fest: Stream em direto`,
  _ = `Selecione a data de um stream em direto do seu jogo para todos os fãs verem. Este evento irá aparecer no calendário oficial do Steam Next Fest e automaticamente na página do seu jogo.`,
  _ = `Steam Next Fest: Horário de atendimento`,
  _ = `Selecione quando os seus fãs poderão entrar em contacto consigo e com a sua equipa para fazer perguntas e conversar na plataforma onde lhe for mais conveniente, seja ela o chat do Steam, Discord, uma sessão de perguntas e respostas no Reddit ou em qualquer outro sítio.`,
