  _ = `Estes anúncios vão aparecer na página principal do grupo e na Central de Notícias personalizada dos seus seguidores.`,
  _ = `Impressões: %1$s; Visualizações: %2$s`,
  _ = `Impressões: %1$s`,
  _ = `Visualizações: %1$s`,
  _ = `O widget de programação de eventos permite a integração de um navegador de eventos futuros na página promocional, dando um maior destaque aos jogos afetados e recompensando a interação com os utilizadores do Steam durante a promoção através da criação de eventos específicos de jogos. Por exemplo, transmissões e conversas em direto são maneiras de criadores de jogos interagirem com o seu público-alvo no Steam.`,
  _ = `É necessário selecionar um ou mais tipos de evento que serão permitidos na programação.`,
  _ = `Selecione um período de duração para a programação. Pode ser idêntico ao do evento ou pode ser diferente se este evento estiver a anunciar uma programação no futuro.`,
  _ = `Por predefinição, a página de promoções vai ter uma %1$s, que será a fonte dos eventos, e poderá ser vista pelos administradores da promoção de imediato e por toda a gente assim que esta página estiver visível.`,
