  _ = `Priorizar demos no widget`,
  _ = `Se esta opção estiver ativa, a ação de jogar a demo terá prioridade ao apresentar os detalhes do jogo e ao passar o cursor por cima. Isto também irá disponibilizar o evento de lançamento da demo no período de duração programado.`,
  _ = `Definir para data de início do evento`,
  _ = `Definir para data de conclusão do evento`,
  _ = `Eventos incluídos:`,
  _ = `Permitir que todos os eventos elegíveis de aplicações participantes apareçam na programação`,
  _ = `A programação irá listar sempre qualquer evento elegível do grupo base e todos os eventos de um tema. Marcar esta opção permite que os eventos elegíveis de qualquer aplicação participante também apareçam na programação. Se desmarcar a opção, só serão listados eventos associados ao grupo comunitário da entidade organizadora ou eventos listados explicitamente nos temas.`,
