  _ = `<1>Os seus jogos</1> - Os seus jogos aparecem na lista de aplicações associadas abaixo e estão prontos para utilização. Basta adicionar e configurar as secções abaixo para apresentar os seus jogos, DLCs, demos e bandas sonoras da maneira mais adequada às suas necessidades.`,
  _ = `<1>Associar mais jogos</1> - Se faltam jogos na lista abaixo, isso significa que não os associou a esta página de criador. Consulte as instruções de como associar jogos à sua página de criador no artigo: <2>Páginas principais de developers e editoras</2>.`,
