  _ = `Publicar o evento irá guardar todas as alterações e tornará o evento visível para quem tiver um link para o mesmo. O evento não aparecerá em listas de eventos, mas os utilizadores poderão vê⁠-⁠lo se tiverem o link.`,
  _ = `Publicar`,
  _ = `Publicar esta página irá guardar todas as alterações e tornará a página de criador potencialmente visível para quem tiver um link para a mesma. Os utilizadores poderão vê⁠-⁠la se tiverem o link. Para fazer desta a sua página de criador, também terá de a ativar depois de a publicar.`,
  _ = `Está pronto para guardar as alterações e publicar este evento?`,
  _ = `O evento ficará visível para o público imediatamente.`,
  _ = `O evento permanecerá oculto até %1$s, que é quando irá começar e ficará automaticamente visível para o público.`,
  _ = `  Pode continuar a editar o conteúdo do evento depois de o publicar.`,
  _ = `Atenção: Assim que tiver publicado este evento, não poderá revertê-lo para o estado precedente da publicação.`,
  _ = `Tem tudo pronto para guardar as alterações e publicar esta página?`,
  _ = `A página só estará visível assim que a definir como ativa no painel de gestão da sua página de criador.`,
  _ = `Pode continuar a editar esta página depois de a publicar.`,
  _ = `(Só para a Valve) Como este grupo tem um mapeamento para um projeto do Crowdin, a publicação irá ativar o envio automático de atualizações para o Crowdin. Pode desativar novamente a qualquer momento.`,
  _ = `Data e hora de publicação personalizadas`,
