  _ = `Só para datas de publicação personalizadas`,
  _ = `Não pode publicar um evento sem primeiro o guardar com sucesso`,
  _ = `Publicação requer aprovação da Valve`,
  _ = `Use o botão à direita para enviar a sua página para análise com, pelo menos, sete dias de antecedência da data de publicação pretendida para garantir que haverá tempo para rever/aprovar quaisquer alterações necessárias.`,
  _ = `Erro interno no editor, não carregámos o texto de tradução, a bloquear gravação/publicação para impedir perda de dados.`,
  _ = `Aviso: O conteúdo deste evento ou anúncio foi alterado em %1$s pelo utilizador %2$s. A versão que começou a editar era de %3$s. Deseja gravar estas alterações por cima?`,
  _ = `Deseja substituir estas alterações?`,
