  _ = `Ocultar até à seguinte data especificada...`,
  _ = `Isto significa que os utilizadores do Steam poderão ver este evento assim que o publicar. Esta é a opção predefinida para anúncios ou funcionalidades lançadas.`,
  _ = `Isto significa que o evento ficará oculto até ao início do evento, ficando automaticamente visível nessa altura.`,
