  _ = `Editar / Migrar`,
  _ = `Este anúncio foi criado numa versão anterior do sistema de anúncios. Não vai ter as novas categorias/ilustrações e não vai ter uma data de conclusão. Editar e depois guardar irá migrar para o novo sistema e permitirá o uso das novas funcionalidades.`,
  _ = `Isto irá eliminar o evento do Steam e remover todos os respetivos metadados (votos, comentários, estatísticas). Se já estiver visível, o evento irá redirecionar para uma página vazia, o que não é recomendado para utilizadores. Esta ação será irreversível.`,
