  _ = `(Limite de %1$s caracteres alcançado. Aparece em listas de eventos)`,
  _ = `Até %1$s caracteres permitidos, sem BBCode. Esta descrição irá aparecer na vista da Biblioteca Steam. O campo de descrição curto é opcional. Se este campo for deixado em branco, será gerado um texto automaticamente a partir do primeiro parágrafo da descrição do evento.`,
  _ = `Opcional: Introduza um resumo do evento de até %1$s caracteres, caso contrário o mesmo será gerado automaticamente.`,
  _ = `Resumo gerado automaticamente: `,
  _ = `%1$s caracteres restantes`,
  _ = `O título do evento, que pode conter até %1$s caracteres. Não é permitido o uso de BBCode no título`,
  _ = `O título desta página para referência. É exibido apenas no seu painel.`,
  _ = `O subtítulo pode conter até %1$s caracteres (só texto, sem BBCode ou qualquer outro tipo de formatação). Este subtítulo será usado juntamente com o título na página de detalhes do evento ou anúncio.`,
  _ = `O resumo pode conter até %1$s caracteres (só texto). O resumo aparece debaixo do título quando apresentado numa lista de eventos ou na área de eventos em destaque. Se não foi fornecido nenhum resumo, o Steam irá gerar um automaticamente a partir da parte inicial da descrição em cada idioma.`,
