  _ = `Mostrar texto automático?`,
  _ = `O título e o subtítulo do evento, juntamente com uma sobreposição para escurecer, serão automaticamente aplicados sobre o lado direito da imagem.`,
  _ = `Este evento ficará temporariamente em destaque por cima da secção de atividade de cada utilizador. Reserve esta opção apenas para eventos importantes e permita um intervalo adequado entre eventos para que não apareça sempre um evento em destaque na página de detalhes do seu jogo.`,
  _ = `Mostrar na secção "Novidades" da biblioteca`,
