  _ = `Mostrar na página de detalhes do jogo na biblioteca`,
  _ = `Mostrar na minha página na Loja Steam`,
  _ = `Tenha atenção ao conteúdo que será apresentado aos utilizadores do Steam que têm o jogo na biblioteca e aos utilizadores que visitarem a página do seu produto na loja. Por exemplo, não seria de bom tom incluir um link para comprar o seu jogo noutra loja. Também deve seguir as %1$s.`,
