  _ = `Se a cor ou a imagem de fundo for muito clara, a seta pode ser difícil de ver. Use esta definição para substituir as cores padrão (branco e cinzento) dos trilhos de navegação do carrossel. Aparecem principalmente em ecrãs mais pequenos, como o do Steam Deck.`,
  _ = `A carregar dados da demo`,
