  _ = `É obrigatório guardar o evento para que possa partilhá‑lo com a sua demo.`,
  _ = `Depois de publicado, o evento ou anúncio irá aparecer na página da demo na biblioteca. Permite a comunicação com fãs que só tenham a sua demo. `,
  _ = `Eventos temáticos: %1$s`,
  _ = `Dia das Bruxas 2022`,
  _ = `Este evento é sobre atualizações ao seu jogo para o Dia das Bruxas de 2022? Se estiver a adicionar novos mapas, skins, ilustrações ou qualquer outro tipo de conteúdo ao seu jogo em celebração do Dia das Bruxas ou se estiver a organizar eventos de tempo limitado com conteúdo especial assustador como desafios ou atividades semelhantes, gostaríamos de saber sobre isso. Estamos a ponderar sobre como promover melhor eventos temáticos a um público maior, mas primeiro precisamos de ter uma ideia melhor acerca do tipo de atividades temáticas que os developers estão a organizar nos seus jogos. Selecione abaixo se este evento for sobre uma atualização para o Dia das Bruxas de 2022.`,
  _ = `Eventos temáticos do Dia das Bruxas`,
  _ = `Está a organizar um evento ou a adicionar conteúdo temático do Dia das Bruxas? Consulte a %1$s para mais informações sobre como participar no "Steam Scream" com um evento temático do Dia das Bruxas no seu jogo.`,
  _ = `Documentação de Evento do Dia das Bruxas "Steam Scream"`,
  _ = `Novo DLC ou adição ao jogo`,
  _ = `Complementos permanentes para o seu jogo com o tema do Dia das Bruxas`,
  _ = `Anuncie um evento temático do Dia das Bruxas no seu jogo, de duração limitada, que pode oferecer aos jogadores itens adicionais, bónus, vantagens, recompensas, experiência, etc. Estes eventos têm uma hora de início e de conclusão.`,
  _ = `Categoria da nomeação para os Prémios Steam`,
  _ = `Selecione uma categoria específica para a qual pretende que os seus fãs nomeiem o seu jogo. Eles poderão nomear o seu jogo para essa categoria no evento!`,
  _ = `A maioria das categorias dos Prémios Steam deste ano são para jogos lançados em %1$s (desde as nomeações dos últimos Prémios Steam em %2$s). Como o seu jogo foi lançado antes dessa data, só poderá ser nomeado para a categoria "Feito Com Amor".`,
  _ = `Para mais informações e para fazer o download de um kit de recursos gráficos dos Prémios Steam com modelos que pode usar para promover o seu jogo, consulte a <1>documentação aqui</1>.`,
  _ = `Este jogo não é elegível para nenhuma categoria dos Prémios Steam. Se acredita tratar-se de um equívoco, entre em contacto com o <1>apoio do Steamworks</1>.`,
  _ = `Confirmação de página da loja invisível`,
