  _ = `Fundo de secções externas sobre esta promoção`,
  _ = `Uma imagem apresentada como o fundo de secções que promovam esta promoção (como a página de "Descontos e eventos"). É usada uma imagem para cada idioma. A imagem irá preencher toda a secção, de uma borda à outra, sendo recortada para se ajustar às dimensões. Por isso, mantenha todos os elementos importantes afastados das bordas, sobretudo na parte superior e na parte inferior.`,
