  _ = `A página desta promoção não apresenta o respetivo logótipo. O logótipo só aparece em páginas que promovam esta promoção.`,
  _ = `Cápsulas da loja`,
  _ = `Estas cápsulas permitem à loja apresentar a página desta promoção nas secções em que jogos costumam ser apresentados: o carrossel de destaques e de produtos recomendados, as centrais da loja e o carrinho de compras. São o mesmo tipo de cápsulas que são enviadas para cada jogo no separador de recursos gráficos da respetiva página na loja e têm as mesmas dimensões.`,
  _ = `Pode enviar todas as cápsulas de uma só vez. Uma imagem é atribuída a uma cápsula automaticamente quando as suas dimensões correspondem exatamente às dessa cápsula; caso contrário, terá de atribuir a imagem manualmente e será pedido que a recorte. Os ficheiros das imagens podem ter o nome de um idioma no fim para que sejam categorizadas nesse idioma (por exemplo: "main_capsule_french.jpg").`,
  _ = `Dê prioridade à identidade visual da promoção. Certifique-se de que o logótipo é claramente legível.`,
  _ = `Aparece nas secções de produtos recomendados e nas secções de destaque mais pequenas na loja.`,
  _ = `Como cápsulas deste tipo são pequenas, o logótipo tem de ficar legível mesmo em dimensões mais reduzidas.`,
  _ = `Utilizada em listas na loja e no carrinho de compras.`,
  _ = `Concebida para destacar a promoção. Não inclua citações, classificações de análises nem prémios.`,
  _ = `Aparece no carrossel de destaques e de produtos recomendados na parte superior da página inicial da Loja Steam.`,
  _ = `Uma imagem vertical concebida para destacar a promoção. Não inclua citações, classificações de análises nem prémios.`,
  _ = `Pode aparecer na parte superior da página inicial durante promoções sazonais e noutras páginas de promoções.`,
  _ = `Imagem heroica na biblioteca`,
  _ = `Os seus recursos da biblioteca estão desatualizados. Atualize estes recursos, que estão visíveis para todos os seus clientes.`,
