  _ = `Logótipo noutras páginas sobre esta promoção`,
  _ = `URL de destino (relativo à página inicial da loja)`,
  _ = `Permite clicar no logótipo na página da promoção para reencaminhar o utilizador para outra secção da loja. Por exemplo, para a página inicial.`,
  _ = `Introduza apenas a parte do endereço que vem depois da página inicial da loja, sem a barra inicial. Por exemplo, introduza category/pins_pegs para encaminhar para https://store.steampowered.com/category/pins_pegs`,
  _ = `Este endereço deve ser relativo à página inicial da loja, por isso remova o prefixo https://store.steampowered.com/. Por exemplo, introduza category/pins_pegs em vez de https://store.steampowered.com/category/pins_pegs`,
  _ = `Remova a barra inicial. Por exemplo, introduza category/pins_pegs em vez de /category/pins_pegs`,
  _ = `Este endereço não pode conter espaços. Por exemplo, introduza category/pins_pegs`,
