  _ = `Falha inesperada ao processar o pedido. Tente mais tarde.`,
  _ = `Tipo de imagem inválido. Só são suportados ficheiros JPG e PNG.`,
  _ = `Não foi encontrada nenhuma ilustração. Tente reenviá-la.`,
  _ = `A sua conta é limitada. Contas limitadas não podem guardar conteúdo de eventos. Consulte https://help.steampowered.com/faqs/view/71D3-35C2-AD96-AA3A para mais informações.`,
  _ = `A secção está marcada como oculta. A mostrar pré‑visualização para edição do grupo de imagens de fundo.`,
  _ = `A secção está marcada como oculta até %1$s. A mostrar pré‑visualização temporária para edição do grupo de imagens de fundo.`,
  _ = `A secção estará marcada como oculta após %1$s. A mostrar pré‑visualização temporária para edição do grupo de imagens de fundo.`,
  _ = `A secção está marcada como oculta por não estar na lista de países permitidos. A mostrar pré‑visualização temporária para edição do grupo de imagens de fundo.`,
  _ = `A secção está marcada como oculta porque o utilizador não tem o pacote. A mostrar pré‑visualização temporária para edição do grupo de imagens de fundo.`,
  _ = `A secção está marcada como oculta porque o utilizador não usou uma unidade de hardware específica. A mostrar pré‑visualização temporária para edição do grupo de imagens de fundo.`,
  _ = `Esta secção do tipo "%1$s" não aparece no modo de pré‑visualização. Trata‑se de uma secção temporária para edição do grupo de imagens de fundo.`,
