  _ = `Exporte e importe ficheiros de localização para gerir a tradução de textos de toda a sua página.`,
  _ = `Exportar ficheiro(s) de tradução...`,
  _ = `Exportar...`,
  _ = `O conteúdo dos eventos pode ser exportado em formato CSV ou XML.`,
  _ = `Comma Separated File (CSV)`,
  _ = `eXtensible Markup Language (XML)`,
  _ = `Isto cria e transfere um ficheiro CSV que contém os campos para todos os idiomas disponíveis no Steam, juntamente com qualquer texto que tenha introduzido anteriormente.`,
  _ = `Atenção: No ficheiro que importar, pode excluir qualquer idioma que não quer alterar com a importação.`,
  _ = `Selecione o formato que prefere para o ficheiro CSV:`,
  _ = `A opção seguinte irá transferir um ficheiro XML por cada idioma que tenha algum conteúdo associado. O ficheiro do idioma inglês será sempre exportado.`,
  _ = `Atenção: Se tiver vários idiomas, o seu browser poderá avisá-lo de que estamos a tentar transferir vários ficheiros. Deve permitir essa ação, pois guardamos cada idioma num ficheiro XML diferente.`,
  _ = `Exportar XML`,
  _ = `Transferir CSV como idiomas por linha`,
  _ = `Transferir CSV como campo de conteúdo por linha`,
  _ = `Idioma por linha`,
  _ = `Idioma por coluna`,
  _ = `Lista de tokens/idiomas`,
  _ = `Importar ficheiro(s) de tradução...`,
  _ = `Importar...`,
  _ = `Para importar texto traduzido para o seu título, subtítulo, resumo e descrição, selecione um ou mais ficheiros para carregar. Usamos a extensão do ficheiro para determinar se o ficheiro se trata de uma importação de XML ou CSV; para XML, usamos o código de idioma da API no fim do nome do ficheiro e antes da extensão para determinar o idioma do conteúdo do ficheiro XML. Deve começar por exportar um ficheiro CSV ou XML para garantir que está a usar o formato correto.`,
  _ = `Importação de tradução concluída. Os seguintes idiomas foram atualizados: %1$s`,
  _ = `Importação de tradução concluída. Nenhuma alteração efetuada.`,
  _ = `Não foi possível interpretar ou reconhecer o ficheiro CSV.`,
  _ = `O ficheiro não tem a extensão ".xml" ou ".csv", não foi possível interpretar o nome do ficheiro: %1$s`,
  _ = `O nome do ficheiro não especifica o código de idioma da API. O ficheiro deve estar no formato <nome do utilizador_<idioma>.xml: %1$s`,
  _ = `Ocorreu um erro ao interpretar e aplicar os dados XML: %1$s`,
  _ = `Exporta o rascunho em inglês para o Crowdin ou importa do Crowdin em todos os outros idiomas`,
  _ = `Exportar para o Crowdin`,
  _ = `Enviar o rascunho atual em inglês para o Crowdin e substituir todas as strings em inglês lá presentes?`,
  _ = `Importar do Crowdin`,
  _ = `Importar do Crowdin todas as strings traduzidas para os seguintes idiomas? Esta ação irá substituir todos os rascunhos locais existentes.`,
  _ = `A página da promoção foi analisada pela Valve e foram impostas as seguintes restrições.`,
  _ = `O URL personalizado da página da promoção já não pode ser editado`,
  _ = `O URL personalizado pode ser usado por destaques. Logo, alterar o URL personalizado poderá invalidar o link.`,
  _ = `Já não é possível adicionar mais aplicações, pacotes ou conjuntos a esta página de promoção.`,
  _ = `A análise da página da promoção destinava-se ao grupo de aplicações, pacotes e conjuntos incluídos; não é possível adicionar mais. Podem ser movidos, reordenados e removidos.`,
  _ = `Não são permitidas mais alterações na página da promoção.`,
  _ = `(Só para a Valve) Enviar atualizações automaticamente para o Crowdin`,
  _ = `Ainda não enviado para o Crowdin`,
  _ = `Se esta opção estiver ativa, as alterações guardadas deste evento serão enviadas para o Crowdin de forma a serem traduzidas. Não use esta opção enquanto o texto do seu evento não estiver estável e pronto para tradução. Se planear efetuar muitas alterações durante algum tempo, desative a opção e reative-a assim que o texto estiver pronto.`,
  _ = `Lembre-se de clicar em "Guardar" depois de alterar esta definição.`,
  _ = `Importar`,
