  _ = `Adicionar outra imagem`,
  _ = `Criar um carrossel de imagens...`,
  _ = `Imagem integrada`,
  _ = `Insira uma imagem integrada no seu texto. A imagem será apresentada no tamanho do texto.`,
  _ = `Converter em link de texto`,
  _ = `Pré-visualização`,
  _ = `Os seguintes erros com o evento atual impedem a publicação deste evento. Por favor, corrija-os e volte a tentar publicá-lo.`,
  _ = `A data e hora de início do evento não foram definidas.`,
  _ = `A data e hora de início (%1$s) do evento são no passado. Ajuste a data e hora de início para o futuro ou para agora. Se fosse permitido agendar eventos para o passado, estes poderiam não ser vistos por utilizadores que visitaram a sua página recentemente, ou seja, a última vez que a teriam lido seria depois do seu evento começar.`,
  _ = `A data e hora de início do evento (%1$s) são antes do permitido. Defina-as para %2$s ou mais tarde.`,
  _ = `A data e hora de conclusão do evento são antes da data e hora de início do evento`,
  _ = `Data/hora de conclusão em falta: É obrigatória uma data/hora de conclusão para este evento, mas não foi fornecida nenhuma.`,
  _ = `A data/hora de visibilidade atual é após a data/hora de início de evento, o que irá impedir o evento de ser visível quando começar.`,
  _ = `A descrição pode ter até 32.000 caracteres no máximo. A descrição no idioma "%1$s" possui mais de 32.000 caracteres.`,
  _ = `O evento tem um título no idioma "%1$s", mas não possui uma descrição traduzida para esse idioma. Ambos são obrigatórios por cada idioma suportado.`,
  _ = `O evento tem uma descrição no idioma "%1$s", mas não possui um título traduzido para esse idioma. Ambos são obrigatórios por cada idioma suportado.`,
  _ = `O evento não possui um título nem uma descrição em nenhum idioma.`,
  _ = `Este evento está definido para aparecer no Steam China, mas ainda não tem título nem descrição no idioma "%1$s".`,
  _ = `Não pode publicar um evento com a categoria "Grande atualização" sem também fornecer pelo menos uma ilustração principal com o idioma inglês. Eventos de grandes atualizações terão um maior destaque na secção de detalhes do seu jogo na biblioteca de jogadores (versão de computador).`,
  _ = `Não pode publicar um evento do tipo "%1$s" sem ter uma imagem de capa em inglês.`,
  _ = `Não pode publicar um evento do tipo "%1$s" sem ter pelo menos uma imagem de capa no idioma "Steam China - Chinês Simplificado".`,
  _ = `Uma promoção só pode ter uma única secção de separadores`,
  _ = `A página da loja deste jogo não está visível de momento. Terá de confirmar este estado no separador Opções antes de publicar.`,
  _ = `O separador "%1$s" não tem %2$s dos %3$s campos necessários.`,
  _ = `Os seguintes avisos podem ser ignorados e não impedem o evento de ser publicado. Contudo, recomendamos que os retifique.`,
  _ = `O evento não possui um título e/ou uma descrição em inglês. O idioma inglês é o idioma principal ou alternativo para muitos utilizadores do Steam. Sem esse idioma, a visibilidade do evento para os clientes do Steam será muito limitada.`,
  _ = `Não foi atribuída nenhuma ilustração ao evento. É possível usar ilustrações personalizadas para ajudar a destacar eventos e torná-los mais cativantes para utilizadores do Steam. Se não for enviada nenhuma ilustração, será usada uma cápsula do jogo.`,
  _ = `Não foi atribuída nenhuma ilustração ao evento. É possível usar ilustrações personalizadas para ajudar a destacar eventos e torná-los mais cativantes para utilizadores do Steam. Se não for enviada nenhuma ilustração, será usado o avatar do grupo.`,
  _ = `A categoria do evento está definida como "Outro", o que irá reduzir drasticamente a visibilidade deste evento. O Steam usa as categorias de eventos para ajudar a encaminhar os eventos aos clientes do Steam. Um evento da categoria "Outro" é suposto ter menos impacto em comparação com os outros e será apresentado para o menor número de utilizadores.`,
  _ = `O subtítulo está disponível em %1$s de %2$s idiomas. Tente garantir que o subtítulo esteja traduzido para todos os idiomas.`,
  _ = `Existem ilustrações traduzidas para %1$s de %2$s idiomas. Isto pode não ser um problema se a ilustração não precisar de ser traduzida. Para idiomas sem uma ilustração, será usada aquela escolhida para o idioma inglês.`,
  _ = `A data de visibilidade foi ajustada para o passado e guardar agora irá tornar o evento visível. Uma vez visível, a data de início não poderá ser alterada e o evento não poderá ser ocultado.`,
  _ = `Há imagens de destaque da loja enviadas para este evento, mas a opção de destaque está desativada. A opção de destaque tem de ser ativada pela Valve para que o banner apareça na sua página na loja.`,
  _ = `O URL de destino do logótipo da página da promoção não é relativo à página inicial da loja, então o logótipo irá encaminhar os utilizadores para uma página inválida. O formato tem de ser category/pins_pegs e não https://store.steampowered.com/category/pins_pegs`,
  _ = `Várias secções deste tipo encontradas`,
  _ = `A página da promoção contém, pelo menos, uma outra secção com o mesmo tipo desta secção. Esta foi concebida para ser usada apenas uma vez numa única página. Tem a certeza de que precisa de várias secções deste tipo?`,
