  _ = `O conteúdo do idioma %1$s está incompleto. %2$s de %3$s secções estão preenchidas.`,
  _ = `O e-mail requer uma ilustração de marca em inglês, que está em falta. O e-mail não pode ser enviado sem uma ilustração em inglês.`,
  _ = `É necessário selecionar pelo menos um grupo de destinatários para receberem o e-mail`,
  _ = `O e-mail não tem texto`,
  _ = `Na secção dos destinatários, tem de selecionar pelo menos uma das opções, entre permissões de developer ou de editora.`,
  _ = `Um URL do YouTube foi especificado mas não é possível interpretá-lo. Por favor, verifique o URL do vídeo.`,
  _ = `E-mails só podem ser configurados e enviados quando o evento correspondente estiver publicado e a decorrer. Por favor, publique o evento primeiro.`,
  _ = `O e-mail tem tradução para %1$s, mas não foi encontrada uma ilustração de marca correspondente a esse idioma. Por isso, será apresentada a ilustração de marca em inglês.`,
  _ = `O e-mail tem traduções para %1$s e %2$s, mas não foram encontradas ilustrações de marca correspondentes a esses idiomas. Por isso, será apresentada a ilustração de marca em inglês.`,
  _ = `O e-mail tem traduções para %1$s, %2$s e mais %3$s outros idiomas, mas não foram encontradas ilustrações de marca correspondentes a esses idiomas todos. Por isso, será apresentada a ilustração de marca em inglês.`,
  _ = `O e-mail tem tradução para %1$s, mas não foi encontrada uma ilustração de marca correspondente a esse idioma.`,
  _ = `Preparação do e-mail`,
  _ = `O evento tem alterações não guardadas. Por favor, guarde o evento antes de preparar o envio deste e-mail`,
  _ = `O e-mail está pronto para o envio. Tem a certeza de que quer bloquear o e-mail para impedir mais alterações? Isto não irá enviar o e-mail, apenas irá prepará-lo para o envio quando você estiver preparado.`,
  _ = `Deparámo-nos com o seguinte aviso. Se quiser, pode corrigir o problema antes de bloquear o conteúdo do e-mail.`,
  _ = `Como parte da preparação, encontrámos os seguintes erros que impedem o envio do e-mail:`,
  _ = `Por favor, aguarde enquanto o e-mail está a ser preparado`,
  _ = `A preparação está concluída. Pode enviar o e-mail quando quiser.`,
