  _ = `"Pre-roll" da transmissão`,
  _ = `Obsoleto: o pipeline de VOD foi desativado e permanece disponível apenas para vídeos antigos, caso necessário. Este vídeo será apresentado no reprodutor de transmissões antes da programação normal e precisa de ter permissões públicas (separadas do estado de lançamento).`,
