  _ = `Se esta opção estiver ativa, as colunas de cada lado do reprodutor serão removidas. Útil apenas quando houver um único stream no evento e as colunas possam distrair os espectadores.`,
  _ = `Ativar modo panorâmico`,
  _ = `Se esta opção estiver ativa, o botão para mostrar/ocultar o chat será exibido. Quando o chat se torna visível, será usado o modo de reprodutor compacto. Quando o chat é fechado, o reprodutor voltará ao modo amplo.`,
  _ = `Permitir que o chat seja mostrado/ocultado`,
