  _ = `ID de sorteio:`,
  _ = `Se houver um sorteio associado à transmissão que anuncia os vencedores no chat, definir um GID de sorteio fará com que as mensagens de chat sejam apresentadas mesmo se o chat estiver fechado, com o intuito de apenas apresentar os anúncios.`,
  _ = `Título da transmissão`,
  _ = `Selecione de uma lista de títulos predefinidos para serem exibidos por cima da sua transmissão na página do seu produto na loja, ou introduza um título personalizado.`,
  _ = `Introduz um título`,
  _ = `Consultar documentação`,
  _ = `Ilustração da transmissão`,
  _ = `Opções de ilustrações de transmissões`,
  _ = `Mostrar banners direito e esquerdo em vez da cápsula do jogo.`,
  _ = `Se esta opção estiver ativa, o banner será usado na Loja Steam em vez das cápsulas do jogo. Isto é útil quando o banner contém informações mais relevantes para o evento do que uma ou mais cápsulas específicas. Útil também quando vários jogos estão a ser transmitidos e só se pretende usar uma única imagem do evento.`,
  _ = `Lista de transmissores permitidos`,
  _ = `O SteamID introduzido é inválido. Deve ser um valor numérico de 64 bits.`,
  _ = `Fundo da transmissão`,
  _ = `Cor interior da gradação do fundo`,
  _ = `Cor exterior da gradação do fundo`,
  _ = `Não foi possível carregar informações do utilizador`,
  _ = `Definição opcional que permite marcar um stream para ter um idioma falado específico para os espectadores. Útil se houver vários streams com idiomas diferentes para este evento, permitindo-nos selecionar o melhor stream predefinido para o utilizador com base no idioma do mesmo.`,
  _ = `Prioridade`,
  _ = `A prioridade desta transmissão em relação às outras. Transmissões de uma maior prioridade serão selecionadas em vez daquelas com menor prioridade. Se várias transmissões tiverem a mesma prioridade, uma será selecionada aleatoriamente como a predefinida.`,
