  _ = `Geral (baixa)`,
  _ = `Tipo de conteúdo transmitido`,
  _ = `Descreve se o conteúdo está a ser transmitido em direto ou em diferido. Neste último caso, se esta é a primeira vez a ser visto na plataforma ou se é uma repetição.`,
