  _ = `Ver perguntas frequentes sobre transmissões`,
  _ = `Enviar feedback`,
  _ = `Denunciar este conteúdo`,
  _ = `Descreve de que maneira este conteúdo viola os Termos de Serviço do Steam. Inclui todas as informações ou links relevantes na tua denúncia. Uma vez enviada, a denúncia não poderá ser removida no futuro.`,
  _ = `Agenda`,
  _ = `Agendamento`,
  _ = `Criar uma agenda/cronograma para aparecer na sua página de eventos?`,
  _ = `Adicionar entrada na agenda`,
  _ = `Remover esta entrada`,
  _ = `Prévia do agendamento integrado`,
