  _ = `Tipo`,
  _ = `Propósito`,
  _ = `Partida competitiva`,
  _ = `Esta é uma partida competitiva entre duas ou mais pessoas/equipas. Assim que a partida terminar, pode atualizar os resultados e incluir as informações sobre o vencedor.`,
  _ = `Transmissão`,
  _ = `Isto chama os utilizadores para verem uma transmissão em direto no Steam ou noutro lugar durante este período de tempo.`,
  _ = `Jogar jogo`,
  _ = `Isto pede aos utilizadores para participarem no evento, iniciando o jogo em questão.`,
  _ = `Na vida real`,
  _ = `Usado para quando a parte do agendamento ocorrer e só é acessível para participantes no local do evento; não pode ser transmitido em direto. Atenção que pode ser melhor não incluir isto no agendamento, uma vez que os seus fãs no Steam não podem participar.`,
  _ = `Data de início`,
  _ = `Especificado em minutos desde o início do evento`,
  _ = `Minutos`,
  _ = `Esta entrada na agenda foi alterada e é diferente da predefinida. Tem a certeza de que pretende eliminá-la? Esta ação não pode ser anulada.`,
  _ = `Temas atuais`,
  _ = `Um tema une um conjunto de eventos relacionados com uma imagem representativa e esquema de cores em comum. Não é necessário para que os eventos apareçam na programação. Exemplos: Evento Principal ou Tema Artístico.`,
  _ = `Nenhum tema definido.`,
