  _ = `Nome da medalha`,
  _ = `Descrição inicial da medalha`,
  _ = `Descreva o método de aquisição da medalha aos utilizadores que ainda não a receberam. Isto também será mostrado a utilizadores sem sessão iniciada. Para poderem fazer progresso na medalha, será pedido que iniciem sessão.`,
