  _ = `Instruções de progresso da medalha - Patamar máximo alcançado`,
  _ = `Este é o patamar de nível máximo da medalha que acreditamos ser razoavelmente alcançável pelo utilizador médio. Instruções podem sugerir outras ações para continuar a aumentar o nível, se isso for possível. `,
