  _ = `(Opcional) URL de imagem de medalha "fantasma"`,
  _ = `Recursos opcionais que, se definidos, serão apresentados ao utilizador ANTES de este adquirir a medalha. Útil quando pretende ocultar detalhes específicos sobre a medalha antes de ser adquirida. O recurso deve ter as dimensões de 160x160 px.`,
