  _ = `Etiquetas personalizadas`,
  _ = `Permite editar diretamente a lista de artigos associados a esta promoção e importar/exportar só a coleção personalizada de etiquetas aplicadas aos artigos da promoção. Isto é usado principalmente para importar um conjunto de etiquetas personalizadas, organizado numa folha de cálculo externa sem modificar as outras etiquetas dos artigos. Além disso, um subconjunto pode ser importado por esta opção, pois não irá remover artigos não listados.`,
