  _ = `Conjunto não permitido`,
  _ = `Este conjunto não pode ser adicionado porque não está associado à página de criador (developer, editora ou série) da página desta promoção. Associe o artigo e atualize a página da promoção para atualizar a associação. Estas aplicações não estão associadas ao criador: (%1$s).`,
  _ = `Pacote não permitido`,
