  _ = `O nome deste valor de faceta. Um valor de faceta é uma opção individual na qual o utilizador pode clicar para filtrar os jogos apresentados nesta secção. Por exemplo, "Primeira Pessoa".`,
  _ = `Texto opcional a ser apresentado à direita deste valor de faceta. Aqui pode deixar uma explicação breve sobre o valor de faceta. Por exemplo, "1-2 horas" para valores de faceta que se aplicam a jogos com um tempo de jogo curto.`,
  _ = `O nome desta faceta. Uma faceta é um grupo de opções relacionadas nas quais o utilizador pode clicar para filtrar os jogos apresentados nesta secção. Por exemplo, "Género".`,
  _ = `Preenche automaticamente as facetas e os valores de faceta de acordo com categorias de marcadores da loja, como "Género" e "Visuais e perspetiva". Após a geração automática, pode editar manualmente cada faceta e valor de faceta conforme necessário.`,
  _ = `Remove valores de faceta que não correspondem a nenhum dos itens nesta secção.`,
  _ = `Qual é o mínimo pretendido de resultados por faceta selecionada? Esta opção irá ocultar todos os termos no menu à esquerda com um número inferior a este. O número é calculado de acordo com os filtros aplicados. Normalmente, 5 é um bom número neste caso.`,
  _ = `Apresenta, no máximo, este número de opções em qualquer categoria principal no menu à esquerda. Por exemplo, não apresenta mais do que este número de géneros numa faceta chamada "Género". Normalmente, 5 é um bom número neste caso.`,
  _ = `Ordena, para cada faceta, os valores de faceta por esta métrica. Para melhores resultados, use por número de correspondências.`,
  _ = `Ordena, em cada faceta, os valores de faceta por ordem alfabética.`,
  _ = `Ordena por ordem decrescente, em cada faceta, os valores de faceta pelo número de itens correspondentes. Por exemplo, numa faceta chamada "Género", "RPG" irá aparecer antes de "Estratégia" se houver mais RPGs nesta secção do que jogos de Estratégia.`,
  _ = `Use esta opção para que os valores de faceta não sejam ordenados pela métrica. Em vez disso, serão apresentados na ordem definida nas listas abaixo.`,
