  _ = `Aceder ao painel`,
  _ = `Para importar texto traduzido para o seu título e descrição, selecione um ou mais ficheiros para carregar. Usamos a extensão para determinar se o ficheiro se trata de uma importação de XML ou CSV; para XML, usamos o código de idioma da API no fim do nome do ficheiro e antes da extensão para determinar o idioma do conteúdo do ficheiro XML. Deve começar por exportar um ficheiro CSV ou XML para garantir que está a usar o formato correto.`,
  _ = `Exporta as traduções atuais para um único ficheiro do tipo selecionado. A exportação para XML irá produzir um único ficheiro com conteúdo no idioma a ser editado. A exportação para CSV irá produzir um único ficheiro com conteúdo em todos os idiomas disponíveis.`,
